function generalTimer(o){endDates[o],startDates[o];const t=(endDates[o]-Date.now())/1e3;var n=Math.floor(t/24/60/60),e=Math.floor(t-86400*n),a=Math.floor(e/3600),r=Math.floor(e-3600*a),l=Math.floor(r/60),s=t%60;function c(o){const t=Math.floor(o);return t<10?"0"+t:t}let d=parseInt(c(n));d>0?$("#countdown-days-"+o).html(d+"<small>d</small>"):$("#countdown-days-"+o).parent().parent().remove(),$("#countdown-hours-"+o).html(c(a)),$("#countdown-mins-"+o).html(c(l)),$("#countdown-secs-"+o).html(c(s)),t<=0&&(clearInterval(countdownTimers[o]),$("#countdown-days-"+o).html("-"),$("#countdown-hours-"+o).html("--"),$("#countdown-mins-"+o).html("--"),$("#countdown-secs-"+o).html("--"),$("#bottom-countdown-container-"+o).remove())}